INSERT INTO projects (id, organization_id, managing_region_id, title, description, project_type, status, created_at, deleted_at, deleted_by) VALUES
('56c1212c-a856-4171-b98d-a939f6819485', '055338d2-390e-5b58-9ddf-f0fedc827382', 'a0000000-0000-0000-0000-000000000001', 'Be the Heart Behind the Donations! Donation Coordinator Needed', 'Samaritan House Denver is seeking consistent, committed volunteers to help receive, sort, organize, and distribute donations. Volunteers may serve Tuesday, Wednesday, and/or Thursday, with a commitment to the same day each week.', 'STANDARD', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('c162b92d-04e9-4cf3-a576-157e627d9888', '055338d2-390e-5b58-9ddf-f0fedc827382', 'a0000000-0000-0000-0000-000000000001', 'Serve a Meal, Share the Love!', 'Help serve a warm meal to individuals and families at Samaritan House Denver! Volunteers will assist kitchen staff while creating a welcoming environment filled with kindness and connection. Ages 13–17 must be accompanied by a parent or guardian.', 'OPEN_DOOR', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('85b09670-f4d0-4b78-81d3-35f6a9ea3405', '055338d2-390e-5b58-9ddf-f0fedc827382', 'a0000000-0000-0000-0000-000000000001', 'Help at Samaritan House Downtown', 'There are lots of ways to help at Samaritan House Downtown! Come help serve a hot meal to the residents or help organize donations in the warehouse!  ', 'STANDARD', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('565625ae-4f1b-46d8-9b91-36801a409274', 'cf970469-2ae6-53dc-a1cb-033a5adee123', 'a0000000-0000-0000-0000-000000000001', 'Volunteer with Us', 'Volunteer with Us-', 'OPEN_DOOR', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('75be5917-9906-403f-b94a-6e52fa3a503d', '0710ac2d-fea0-5140-8527-249ec170ccbf', 'a0000000-0000-0000-0000-000000000001', '2026 Children''s Holiday Party!', 'Children’s Holiday Party is our largest community outreach event of the year! Thank you for joining us as a volunteer.
