('b10fe641-404d-44ef-bbf3-669d80d6e40d', '0710ac2d-fea0-5140-8527-249ec170ccbf', 'a0000000-0000-0000-0000-000000000001', 'Volunteers Needed! Tax Help Colorado', 'We are recruiting volunteers for the 2027 tax season! Volunteering is easy and fun. Our staff provides all the training – no financial experience is needed. Join our Volunteer Kickoff to learn how you can join this important work.', 'STANDARD', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('fab9882d-f968-4de6-a0e0-1084e956c93a', '0710ac2d-fea0-5140-8527-249ec170ccbf', 'a0000000-0000-0000-0000-000000000001', 'Community Corner at Mile High United Way', 'Volunteer with the Marketplace in the Joan Leprino Community Corner at Mile High United Way! The Marketplace provides families and individuals with the essential supplies they need to thrive, including food, cooking supplies, and items for babies, personal care and cleaning.', 'OPEN_DOOR', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('125950a9-67e8-4601-af19-5c10fbdb1dbf', 'd6014018-7b8e-55b3-94ca-aa8443939c00', 'a0000000-0000-0000-0000-000000000001', ' Remote Volunteer Needed! Culture and Member Service Chat Host!', ' Mission Success Hosts play a vital role in bringing this vision to life. As the first point of human connection for new Aid Arena members, Mission Success Hosts help foster belonging, engagement, and trust from day one.
', 'STANDARD', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('66970e50-eb34-4cc6-ad74-7558832fb219', '8950d2f9-0466-5160-81d4-6f38c4a92693', 'a0000000-0000-0000-0000-000000000001', 'Denver Metro Event Volunteer', 'We are looking for volunteers who can help run our vendor booth at community events around the Denver Metro Area. If you are a creative and value the meaningful impact of movement and play then this volunteer role is for you!', 'OPEN_DOOR', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('8e854a8d-1d1b-47d9-b6af-bbe7f4b4c387', '259f9c1d-0103-5dfc-ba71-a8c644389fb6', 'a0000000-0000-0000-0000-000000000001', 'Vitalant- Boulder Volunteers', 'Volunteering to donate blood at Vitalant is one important way to join our lifesaving team, but we also offer other volunteer opportunities that make a difference in your community...', 'STANDARD', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
