('da8c229b-50a8-4959-97ac-6fa10a0ea4a1', 'a8ce26c3-be21-552e-8710-91d36374da2e', 'a0000000-0000-0000-0000-000000000001', 'Daily Warehouse Activities - Community Food Share', 'Sort and repackage food. Restock shelves.', 'OPEN_DOOR', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('488d1f76-50c6-4b9c-84ba-fb0fa049bf47', '8950d2f9-0466-5160-81d4-6f38c4a92693', 'a0000000-0000-0000-0000-000000000001', 'Hospice Volunteer', 'Share your time and talent with a hospice patient by talking with them, listening to their stories, help them label photos, read to them, make art, or even hold their hand. There are so many ways to provide support to someone at end-of-life.', 'STANDARD', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('61fc9047-d153-4419-a4f3-494dc753a1c1', '8950d2f9-0466-5160-81d4-6f38c4a92693', 'a0000000-0000-0000-0000-000000000001', 'Vigil Volunteer', 'A Vigil Volunteer creates a safe and sacred space for an actively dying patient by sitting bedside with them. You might read, hold their hand, play music, or sit in silence so they know you are present. ', 'OPEN_DOOR', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('854c37c8-9ce1-4b02-92f6-d5c65b775b8f', '343d70ad-f251-51c2-b57b-2680945a19bc', 'a0000000-0000-0000-0000-000000000001', 'Spiritual Support Volunteer', 'Brighton Hospice seeks spiritually minded people who want to support hospice patients by reading spiritual material and / or praying with them. ', 'STANDARD', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('a4f3e754-76ea-4c51-b222-8698e34a4ba7', '8950d2f9-0466-5160-81d4-6f38c4a92693', 'a0000000-0000-0000-0000-000000000001', 'Veteran-to-Veteran Volunteer', 'Did you serve in the Military? Help veterans at the end of their lives by becoming a hospice volunteer. With so many veterans in our community, you have a real opportunity to honor a veteran by providing a listening ear and creating a sacred space that only another veteran can. 
', 'OPEN_DOOR', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('acc05bed-0331-4bd3-8628-eddeba03f8c6', '343d70ad-f251-51c2-b57b-2680945a19bc', 'a0000000-0000-0000-0000-000000000001', 'Fabulous Fun Facility Volunteer ', 'Enjoy spending time with seniors? Share your time and talent to bring joy by helping with events. ', 'STANDARD', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('c1cd0f04-995b-4676-a588-764b753bf0b9', '8950d2f9-0466-5160-81d4-6f38c4a92693', 'a0000000-0000-0000-0000-000000000001', 'Companionship and Transportation for Seniors', 'Porchlight Friends'' volunteer companions offer  companionship and transportation for older adults.  Volunteer companions assist with projects, have a cup of coffee and conversation, and provide rides for essential errands.', 'OPEN_DOOR', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('620df941-9ef8-40d4-9460-ddae8e230b10', '98f4a007-425d-52cc-a05d-60e901a4c398', 'a0000000-0000-0000-0000-000000000001', 'Childcare Support', 'Hang out with kids in our program while their parents attend self-sufficiency classes. Afternoon/evening shifts between 5 and 7 PM.', 'STANDARD', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
('e2cd0307-787c-4f20-b997-3f4ac8589d51', '98f4a007-425d-52cc-a05d-60e901a4c398', 'a0000000-0000-0000-0000-000000000001', 'Front Desk Greeter', 'Volunteer at the front desk at Colorado House! Greet visitors, answer phones, and help keep shared spaces running smoothly. Perfect for individuals, youth 16+, or families.', 'OPEN_DOOR', 'ACTIVE', '2026-06-01T00:00:00+00:00', NULL, NULL),
